import { test, expect } from '@playwright/test';

test.describe('Checkout Form - Card Expiry Validation', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should accept valid card expiry in MM/YY format', async () => {
    // Fill in the card expiry field with valid MM/YY format
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);
    await expiryInput.fill('12/25');

    // Verify the input accepts the value
    await expect(expiryInput).toHaveValue('12/25');

    // Check that no error message appears
    const errorMessage = page.getByText(/invalid.*expiry|expiration.*invalid|please enter.*valid.*date/i);
    await expect(errorMessage).not.toBeVisible();
  });

  test('should reject card expiry in invalid format', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);

    // Try entering expiry in wrong format (MM-YY)
    await expiryInput.fill('12-25');
    await expiryInput.blur();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid.*format|must be.*MM\/YY|please use.*MM\/YY/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should reject expired card dates', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);

    // Try entering a past date
    await expiryInput.fill('01/20');
    await expiryInput.blur();

    // Verify expiration error message
    const errorMessage = page.getByText(/expired|past.*date|date.*past/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should validate month is between 01-12', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);

    // Try entering invalid month (13)
    await expiryInput.fill('13/25');
    await expiryInput.blur();

    // Verify month validation error
    const errorMessage = page.getByText(/invalid.*month|month.*must be|01.*12/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should auto-format input to MM/YY when user types numbers', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);

    // Type numbers without slash
    await expiryInput.fill('1225');

    // Verify it's formatted as MM/YY
    const value = await expiryInput.inputValue();
    expect(value).toMatch(/^\d{2}\/\d{2}$/);
  });

  test('should clear validation error when valid expiry is entered', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);

    // First enter invalid format
    await expiryInput.fill('invalid');
    await expiryInput.blur();

    // Verify error appears
    let errorMessage = page.getByText(/invalid.*format|must be.*MM\/YY/i);
    await expect(errorMessage).toBeVisible();

    // Now enter valid format
    await expiryInput.clear();
    await expiryInput.fill('12/25');
    await expiryInput.blur();

    // Verify error is gone
    await expect(errorMessage).not.toBeVisible();
  });

  test('should prevent form submission with invalid expiry', async () => {
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);
    const submitButton = page.getByRole('button', { name: /submit|pay|checkout|complete/i });

    // Enter invalid expiry
    await expiryInput.fill('99/99');
    await expiryInput.blur();

    // Try to submit
    await submitButton.click();

    // Verify form was not submitted (still on checkout page)
    await expect(page).toHaveURL(/checkout/);

    // Verify error message is visible
    const errorMessage = page.getByText(/invalid|error/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should allow form submission with valid expiry', async () => {
    // Fill in all required fields
    const cardNumberInput = page.getByLabel(/card number|card no/i);
    const expiryInput = page.getByLabel(/card expiry|expiration date|exp date/i);
    const cvvInput = page.getByLabel(/cvv|cvc|security code/i);
    const submitButton = page.getByRole('button', { name: /submit|pay|checkout|complete/i });

    // Fill in valid data
    await cardNumberInput.fill('4532015112830366');
    await expiryInput.fill('12/25');
    await cvvInput.fill('123');

    // Submit form
    await submitButton.click();

    // Verify successful submission (redirect or success message)
    await page.waitForNavigation({ waitUntil: 'networkidle' }).catch(() => {});
    const successMessage = page.getByText(/success|thank you|order.*confirmed|payment.*successful/i);
    const isSuccess = await successMessage.isVisible().catch(() => false);

    if (isSuccess) {
      await expect(successMessage).toBeVisible();
    } else {
      // If no success message, verify we're on a different page
      expect(page.url()).not.toContain('checkout');
    }
  });
});
